from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def one(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise SystemExit(f"{label}: anchor not found")
    return text.replace(old, new, 1)


p = ROOT / "index.html"
t = p.read_text(encoding="utf-8")

comparison_js = r'''function aiComparisonCatalog(g){let input=g?.input_snapshot&&typeof g.input_snapshot==='object'?g.input_snapshot:{},rows=Array.isArray(input.exercise_catalog)?input.exercise_catalog:[];return new Map(rows.map(x=>[String(x?.id||''),x]))}function aiComparisonDays(g,side){let input=g?.input_snapshot&&typeof g.input_snapshot==='object'?g.input_snapshot:{},before=Array.isArray(input.current_draft?.days)?input.current_draft.days:[],out=g?.output_snapshot&&typeof g.output_snapshot==='object'?g.output_snapshot:{},after=Array.isArray(out.days)?out.days:Array.isArray(out.plan?.days)?out.plan.days:[],rows=side==='before'?before:after,target=Number(g?.target_day_number);if(g?.scope==='day'&&Number.isInteger(target)&&target>0)rows=rows.filter(d=>Number(d?.day_number)===target);return rows}function aiComparisonExercise(ex,catalog){let meta=catalog.get(String(ex?.exercise_id||''))||{},unit=ex?.prescription_unit||meta?.prescription_unit||'reps';return {name:meta?.name||ex?.name||'Ejercicio',muscle:meta?.primary_muscle||ex?.primary_muscle||'Sin grupo',unit}}function aiComparisonPrescription(ex,catalog){let info=aiComparisonExercise(ex,catalog),min=ex?.rep_min,max=ex?.rep_max,range=min==null&&max==null?'—':String(min??'—')+'–'+String(max??'—'),target=info.unit==='seconds'?range+' s':range+' reps',rir=ex?.rir_target==null?'—':ex.rir_target,rest=ex?.rest_seconds==null?'—':ex.rest_seconds+' s';return (ex?.target_sets??'—')+' series · '+target+' · RIR '+rir+' · descanso '+rest}function aiComparisonStats(days,catalog){let sets=0,slots=0,muscles={};for(const d of days||[])for(const ex of Array.isArray(d?.exercises)?d.exercises:[]){slots++;let n=Number(ex?.target_sets)||0;sets+=n;let m=aiComparisonExercise(ex,catalog).muscle;muscles[m]=(muscles[m]||0)+n}return {days:(days||[]).length,slots,sets,muscles}}function aiComparisonIndex(days,catalog){let map=new Map;for(const d of days||[]){let day=Number(d?.day_number)||0;for(const ex of Array.isArray(d?.exercises)?d.exercises:[]){let key=day+'|'+String(ex?.exercise_id||''),info=aiComparisonExercise(ex,catalog);map.set(key,{day,dayName:d?.name||('Día '+day),dayFocus:d?.focus||'',ex,info})}}return map}function aiComparisonDeltaText(n){return (n>0?'+':'')+String(n)}function aiComparisonRoutineHtml(days,catalog){if(!days.length)return '<div class="card muted">Sin estructura previa disponible.</div>';return days.map(d=>'<div class="card" style="margin-top:8px"><div class="row"><div class="grow"><b>Día '+esc(d?.day_number??'—')+' · '+esc(d?.name||'Sin nombre')+'</b><div class="muted">'+esc(d?.focus||'Sin enfoque')+'</div></div><span class="pill blue">'+esc(d?.estimated_minutes==null?'—':d.estimated_minutes+' min')+'</span></div><div style="margin-top:8px">'+(Array.isArray(d?.exercises)?d.exercises:[]).map(ex=>{let info=aiComparisonExercise(ex,catalog);return '<div style="padding:8px 0;border-top:1px solid var(--b)"><b>'+esc((ex?.exercise_order??'—')+' · '+info.name)+'</b><div class="muted">'+esc(info.muscle)+' · '+esc(aiComparisonPrescription(ex,catalog))+'</div></div>'}).join('')+'</div></div>').join('')}async function openAiGenerationComparison(generationId){try{if(!generationId)throw Error('Generación no disponible.');let rows=await table('ai_program_generations','id=eq.'+encodeURIComponent(generationId)+'&select=id,scope,target_day_number,status,input_snapshot,output_snapshot,warnings,conflicts,explanations,created_at,applied_at'),g=rows?.[0];if(!g)throw Error('No se encontró la generación.');let catalog=aiComparisonCatalog(g),before=aiComparisonDays(g,'before'),after=aiComparisonDays(g,'after'),bs=aiComparisonStats(before,catalog),as=aiComparisonStats(after,catalog),bi=aiComparisonIndex(before,catalog),ai=aiComparisonIndex(after,catalog),added=[],removed=[],modified=[],dayChanges=[];for(const [k,v] of ai)if(!bi.has(k))added.push(v);for(const [k,v] of bi)if(!ai.has(k))removed.push(v);for(const [k,b] of bi){let a=ai.get(k);if(!a)continue;let fields=[],bx=b.ex,ax=a.ex;if(Number(bx?.exercise_order)!==Number(ax?.exercise_order))fields.push('orden '+(bx?.exercise_order??'—')+' → '+(ax?.exercise_order??'—'));if(Number(bx?.target_sets)!==Number(ax?.target_sets))fields.push('series '+(bx?.target_sets??'—')+' → '+(ax?.target_sets??'—'));let bu=bx?.prescription_unit||b.info.unit||'reps',au=ax?.prescription_unit||a.info.unit||'reps';if(bu!==au)fields.push('unidad '+bu+' → '+au);if(bx?.rep_min!==ax?.rep_min||bx?.rep_max!==ax?.rep_max)fields.push((au==='seconds'?'segundos ':'reps ')+(bx?.rep_min??'—')+'–'+(bx?.rep_max??'—')+' → '+(ax?.rep_min??'—')+'–'+(ax?.rep_max??'—'));if(Number(bx?.rir_target)!==Number(ax?.rir_target))fields.push('RIR '+(bx?.rir_target??'—')+' → '+(ax?.rir_target??'—'));if(Number(bx?.rest_seconds)!==Number(ax?.rest_seconds))fields.push('descanso '+(bx?.rest_seconds??'—')+' → '+(ax?.rest_seconds??'—')+' s');if(fields.length)modified.push({...a,fields})}for(const bd of before){let ad=after.find(x=>Number(x?.day_number)===Number(bd?.day_number));if(ad&&((bd?.name||'')!==(ad?.name||'')||(bd?.focus||'')!==(ad?.focus||'')||Number(bd?.estimated_minutes)!==Number(ad?.estimated_minutes)))dayChanges.push({day:Number(bd?.day_number)||0,before:bd,after:ad})}let muscleNames=[...new Set([...Object.keys(bs.muscles),...Object.keys(as.muscles)])],muscleRows=muscleNames.map(name=>({name,before:bs.muscles[name]||0,after:as.muscles[name]||0})).filter(x=>x.before!==x.after).sort((a,b)=>Math.abs(b.after-b.before)-Math.abs(a.after-a.before)||a.name.localeCompare(b.name,'es'));let changes=[...added.map(x=>'<div class="row" style="align-items:flex-start"><span class="pill green">NUEVO</span><div class="muted grow"><b>'+esc(x.info.name)+'</b> · Día '+esc(x.day)+' · '+esc(aiComparisonPrescription(x.ex,catalog))+'</div></div>'),...removed.map(x=>'<div class="row" style="align-items:flex-start"><span class="pill red">QUITADO</span><div class="muted grow"><b>'+esc(x.info.name)+'</b> · Día '+esc(x.day)+'</div></div>'),...modified.map(x=>'<div class="row" style="align-items:flex-start"><span class="pill warn">AJUSTE</span><div class="muted grow"><b>'+esc(x.info.name)+'</b> · Día '+esc(x.day)+' · '+x.fields.map(esc).join(' · ')+'</div></div>'),...dayChanges.map(x=>'<div class="row" style="align-items:flex-start"><span class="pill blue">DÍA</span><div class="muted grow"><b>Día '+esc(x.day)+'</b> · '+esc(x.before?.focus||'Sin enfoque')+' → '+esc(x.after?.focus||'Sin enfoque')+'</div></div>')];let scopeLabel=g.scope==='day'?'Día '+esc(g.target_day_number):'Rutina completa',summary=String(g?.explanations?.summary||'').trim();$('#modal').innerHTML='<div class="modal"><div class="card" style="width:min(96vw,1180px);max-height:92vh;overflow:auto"><div class="row"><div class="grow"><div class="ey">COMPARACIÓN IA · '+scopeLabel+'</div><h2 style="margin-bottom:4px">Rutina anterior vs nueva rutina</h2><div class="muted">Snapshot exacto tomado antes de generar · '+esc(aiReviewDate(g.created_at))+'</div></div><button id="closeAiComparison" class="btn small">✕</button></div><div class="metrics" style="margin-top:14px"><div class="metric"><span>Días</span><b>'+esc(bs.days)+' → '+esc(as.days)+'</b></div><div class="metric"><span>Ejercicios</span><b>'+esc(bs.slots)+' → '+esc(as.slots)+'</b></div><div class="metric"><span>Series totales</span><b>'+esc(bs.sets)+' → '+esc(as.sets)+'</b><div class="muted">'+esc(aiComparisonDeltaText(as.sets-bs.sets))+'</div></div><div class="metric"><span>Cambios detectados</span><b>'+esc(added.length+removed.length+modified.length+dayChanges.length)+'</b></div></div><div class="card" style="margin-top:12px;border-color:#274a73"><div class="row"><h3 class="grow" style="margin:0">Resumen de cambios</h3><span class="pill blue">BORRADOR · NO PUBLICADO</span></div>'+(summary?'<div class="muted" style="margin-top:8px">'+esc(summary)+'</div>':'')+(muscleRows.length?'<div class="metrics" style="margin-top:10px">'+muscleRows.map(x=>'<div class="metric"><span>'+esc(x.name)+'</span><b>'+esc(x.before)+' → '+esc(x.after)+'</b><div class="muted">'+esc(aiComparisonDeltaText(x.after-x.before))+' series</div></div>').join('')+'</div>':'<div class="muted" style="margin-top:8px">Sin cambios de series por grupo muscular.</div>')+'<div class="stack" style="margin-top:12px">'+(changes.length?changes.join(''):'<div class="muted">No se detectaron cambios estructurales.</div>')+'</div></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px;margin-top:12px"><section><div class="ey">ANTES</div><h3>Rutina anterior</h3>'+aiComparisonRoutineHtml(before,catalog)+'</section><section><div class="ey">DESPUÉS</div><h3>Nueva rutina</h3>'+aiComparisonRoutineHtml(after,catalog)+'</section></div>'+aiReviewWarnings(g.warnings)+aiReviewConflicts(g.conflicts)+'<div class="row" style="margin-top:14px"><div class="muted grow">La comparación es informativa. Publicar sigue siendo una acción separada del coach.</div><button id="closeAiComparisonBottom" class="btn primary">CONTINUAR REVISANDO BORRADOR</button></div></div></div>';let close=()=>$('#modal').innerHTML='';$('#closeAiComparison').onclick=close;$('#closeAiComparisonBottom').onclick=close}catch(e){toast('No se pudo abrir la comparación: '+String(e?.message||e))}}'''

t = one(t, "let aiProgramCapabilityCache=null;", comparison_js + "let aiProgramCapabilityCache=null;", "insert comparison module")
